args.command:
cd /tau/self; node - <<'EOF'
import { mkdirSync, readFileSync } from 'node:fs'
import { args, run } from '@sleepymug/tau-api'

const { tau, runs, call } = args() as { tau: string; runs: number; call: { files: { out: string }; args: object } }
const ran = await Promise.all(Array.from({ length: runs }, async (_, i) => {
  const out = `/tmp/run-${i + 1}/report.txt`
  mkdirSync(`/tmp/run-${i + 1}`, { recursive: true })
  const result = await run(tau, { files: { ...call.files, out }, args: call.args })
  return { run: i + 1, ...result, left: result.ok ? readFileSync(out, 'utf8') : null }
}))
console.log(JSON.stringify(ran, null, 2))
EOF
